#if !defined(SPIRAL_MATRIX_H)
#define SPIRAL_MATRIX_H

#include <cstdint>
#include <vector>

namespace spiral_matrix {

std::vector<std::vector<uint32_t>> spiral_matrix(unsigned int size);

}  // namespace spiral_matrix

#endif  // SPIRAL_MATRIX_H

#include "spiral_matrix.h"

namespace spiral_matrix {

std::vector<std::vector<uint32_t>> spiral_matrix(unsigned int size) {
    std::vector<std::vector<uint32_t>> matrix(size, std::vector<uint32_t>(size, 0));

    unsigned int top = 0;
    unsigned int bottom = size;
    unsigned int left = 0;
    unsigned int right = size;
    uint32_t value = 1;

    while (top < bottom && left < right) {
        for (unsigned int col = left; col < right; ++col) {
            matrix[top][col] = value++;
        }
        ++top;

        for (unsigned int row = top; row < bottom; ++row) {
            matrix[row][right - 1] = value++;
        }
        --right;

        if (top < bottom) {
            for (unsigned int col = right; col > left; --col) {
                matrix[bottom - 1][col] = value++;
            }
            --bottom;
        }

        if (left < right) {
            for (unsigned int row = bottom; row > top; --row) {
                matrix[row][left] = value++;
            }
            ++left;
        }
    }

    return matrix;
}

}  // namespace spiral_matrix

